package vn.edu.bookstore.dao;
import vn.edu.bookstore.config.DB_24133063;import vn.edu.bookstore.model.User_24133063;import org.mindrot.jbcrypt.BCrypt;import java.sql.*;
public class UserDAOImpl_24133063 implements UserDAO_24133063 {
 public User_24133063 byEmail(String email)throws SQLException {try(Connection c=DB_24133063.open();PreparedStatement s=c.prepareStatement("SELECT id,email,fullname,passwd,is_admin,is_active FROM users WHERE email=?")){s.setString(1,email);try(ResultSet r=s.executeQuery()){if(!r.next())return null;User_24133063 u=new User_24133063();u.id=r.getInt(1);u.email=r.getString(2);u.fullname=r.getString(3);u.passwd=r.getString(4);u.admin=r.getBoolean(5);u.active=r.getBoolean(6);return u;}}}
 public void create(String email,String name,String phone,String hash,String otpHash)throws SQLException {try(Connection c=DB_24133063.open();PreparedStatement s=c.prepareStatement("INSERT INTO users(email,fullname,phone,passwd,otp_hash,otp_expiry) VALUES(?,?,?,?,?,DATEADD(MINUTE,10,SYSDATETIME()))")){s.setString(1,email);s.setString(2,name);s.setString(3,phone);s.setString(4,hash);s.setString(5,otpHash);s.executeUpdate();}}
 public boolean activate(String email,String otp)throws SQLException {try(Connection c=DB_24133063.open()){c.setAutoCommit(false);try(PreparedStatement s=c.prepareStatement("SELECT otp_hash FROM users WITH (UPDLOCK,ROWLOCK) WHERE email=? AND is_active=0 AND otp_expiry>SYSDATETIME()")){s.setString(1,email);try(ResultSet r=s.executeQuery()){if(!r.next()){c.rollback();return false;}String hash=r.getString(1);if(hash==null||!BCrypt.checkpw(otp,hash)){c.rollback();return false;}}}try(PreparedStatement s=c.prepareStatement("UPDATE users SET is_active=1,otp_hash=NULL,otp_expiry=NULL WHERE email=?")){s.setString(1,email);s.executeUpdate();}c.commit();return true;}}
 public void login(int id)throws SQLException {try(Connection c=DB_24133063.open();PreparedStatement s=c.prepareStatement("UPDATE users SET last_login=SYSDATETIME() WHERE id=?")){s.setInt(1,id);s.executeUpdate();}}
}